<script setup lang="ts">
import { unwrap } from '~/api/client'; import { displayError } from '~/utils/errors'; import { formatDate, formatRupiah, statusLabel } from '~/utils/format';
definePageMeta({ middleware: 'auth' }); const api = useMarketplaceApi(); const cartApi = useCart();
const { data, error, status, refresh } = await useAsyncData('buyer-refunds', async () => { if (!cartApi.account.value) await cartApi.load(); return unwrap(await api.GET('/buyer-accounts/{buyerAccountId}/refunds', { params: { path: { buyerAccountId: cartApi.account.value!.id }, query: { limit: 100 } }, cache: 'no-store' })); }, { server: false });
useSeoMeta({ title: 'Refund — Niaga' });
</script>
<template><main id="main-content" class="page-shell"><BuyerNav/><div class="section-heading"><div><p class="eyebrow">Pengembalian dana</p><h1>Riwayat refund</h1></div></div><ApiState :pending="status === 'idle' || status === 'pending'" :error="error ? displayError(error) : null" :empty="Boolean(data && !data.items.length)" empty-title="Belum ada refund" empty-message="Refund yang disetujui atau sedang diproses akan tampil di sini." @retry="refresh"><div class="order-list"><article v-for="refund in data?.items" :key="refund.id" class="surface order-card"><header><div><strong>Refund {{ refund.id.slice(0,8) }}</strong><small>{{ formatDate(refund.created_at) }}</small></div><span class="badge" :class="{ 'badge--warning': ['REQUESTED','PROCESSING','UNKNOWN'].includes(refund.state) }">{{ statusLabel(refund.state) }}</span></header><p>{{ refund.reason }}</p><div v-for="(line,index) in refund.lines" :key="index" class="summary-line"><span>{{ statusLabel(line.component) }}</span><strong>{{ formatRupiah(line.amount) }}</strong></div><footer><span>{{ refund.state === 'SUCCEEDED' ? 'Dana telah dikembalikan' : 'Nilai refund' }}</span><strong>{{ formatRupiah(refund.amount) }}</strong></footer></article></div></ApiState></main></template>
